import app from 'flarum/forum/app';
import Button from 'flarum/common/components/Button';
import classList from 'flarum/common/utils/classList';
export default class UploadPollImageButton extends Button {
  loading = false;
  uploadedImageUrl = false;
  fileName = (() => undefined)();
  view(vnode) {
    this.attrs.loading = this.loading;
    this.attrs.className = classList(this.attrs.className, 'Button');
    const imageUrl = this.getImageUrl();
    if (imageUrl) {
      this.attrs.onclick = this.remove.bind(this);
      return m("div", null, m("p", null, m("img", {
        src: imageUrl,
        alt: ""
      })), m("p", null, super.view({
        ...vnode,
        children: app.translator.trans('fof-polls.forum.upload_image.remove_button')
      })));
    } else {
      this.attrs.onclick = this.upload.bind(this);
    }
    return super.view({
      ...vnode,
      poll: undefined,
      children: app.translator.trans('fof-polls.forum.upload_image.upload_button')
    });
  }

  /**
   * Prompt the user to upload an image.
   */
  upload() {
    if (this.loading) return;
    this.$input = $('<input type="file">');
    this.$input.appendTo('body').hide().trigger('click').on('change', e => {
      const body = new FormData();
      // @ts-expect-error
      body.append(this.attrs.name, $(e.target)[0].files[0]);
      this.loading = true;
      m.redraw();
      app.request({
        method: 'POST',
        url: this.resourceUrl(),
        serialize: raw => raw,
        body
      }).then(this.success.bind(this), this.failure.bind(this));
    });
  }

  /**
   * Remove the image.
   */
  remove() {
    this.loading = true;
    m.redraw();
    let fileName = undefined;
    if (!this.attrs.poll?.exists && !this.attrs.option?.exists) {
      fileName = this.fileName;
    }
    app.request({
      method: 'DELETE',
      url: this.resourceUrl(fileName)
    }).then(upload => {
      if (this.attrs.poll?.exists) {
        this.attrs.poll.pushAttributes({
          image: null,
          imageUrl: null,
          isImageUpload: false
        });
      }
      if (this.attrs.option?.exists) {
        this.attrs.option.pushAttributes({
          imageUrl: false
        });
      }
      return upload;
    }).then(this.success.bind(this), this.failure.bind(this));
  }
  resourceUrl(fileName) {
    if (fileName === void 0) {
      fileName = undefined;
    }
    let url = app.forum.attribute('apiUrl') + '/polls/' + this.attrs.name;
    const poll = this.attrs.poll;
    const option = this.attrs.option;
    if (fileName) {
      url += '/name/' + fileName;
    } else {
      if (poll?.exists) url += '/' + poll?.id();
      if (option?.exists) url += '/' + option?.id();
    }
    return url;
  }
  getImageUrl() {
    if (this.uploadedImageUrl !== false) {
      return this.uploadedImageUrl;
    }
    return this.attrs.poll?.imageUrl() || this.attrs.option?.imageUrl();
  }

  /**
   * After a successful upload/removal, redraw the page.
   *
   * @param {PollUploadObject} response
   * @protected
   */
  success(response) {
    this.loading = false;
    this.uploadedImageUrl = response?.fileUrl;
    this.fileName = response?.fileName;

    // Update the store model so other components (PollImage, PostPoll) reflect the change immediately.
    // Push the filename (not the full URL) so it matches what the API persists.
    if (response?.fileName) {
      if (this.attrs.poll?.exists) {
        this.attrs.poll.pushAttributes({
          image: response.fileName,
          imageUrl: response.fileUrl,
          isImageUpload: true
        });
      }
      if (this.attrs.option?.exists) {
        this.attrs.option.pushAttributes({
          imageUrl: response.fileUrl,
          image_url: response.fileName,
          isImageUpload: true
        });
      }
    }
    this.attrs.onUpload?.(response?.fileName);
    m.redraw();
    this.$input?.remove();
  }

  /**
   * If upload/removal fails, stop loading.
   *
   * @param {object} response
   * @protected
   */
  failure(response) {
    this.loading = false;
    m.redraw();
    this.$input?.remove();
  }
}
flarum.reg.add('framio-engagement', 'polls/forum/components/UploadPollImageButton', UploadPollImageButton);